+#[test]
+fn a_3_2_plane_over_every_pose_of_a_turning_table_passes() {
+    let (_, status, warns) = face_on(Rig::TableA, 30.0, 0.0, 20.0);
+    assert_eq!(status, OpStatus::Ok);
